class Solution:
    def canPartition(self, nums: List[int]) -> bool:
        total = sum(nums)
        if total % 2 != 0:
            return False
        target = total // 2
        dp = [False] * (target + 1)
        dp[0] = True
        for num in nums:
            for j in range(target, num - 1, -1):
                dp[j] = dp[j] or dp[j - num]
        return dp[target]

class Solution:
    def findAnagrams(self, s: str, p: str) -> List[int]:
        from collections import Counter
        if len(s) < len(p):
            return []
        p_count = Counter(p)
        s_count = Counter(s[:len(p)])
        res = []
        if s_count == p_count:
            res.append(0)
        for i in range(len(p), len(s)):
            s_count[s[i]] += 1
            left_char = s[i - len(p)]
            s_count[left_char] -= 1
            if s_count[left_char] == 0:
                del s_count[left_char]
            if s_count == p_count:
                res.append(i - len(p) + 1)
        return res

